abstract class DataImporter {
    fun import() { // fixed sequence, can't be overridden
        val raw = readSource()
        val parsed = parse(raw)
        save(parsed)
    }
    abstract fun readSource(): String
    abstract fun parse(raw: String): List<Record>
    open fun save(records: List<Record>) { database.insertAll(records) }
}

interface PaymentProcessor { fun pay(amountCents: Long) }

class LegacySdkAdapter(private val legacySdk: OldPaymentSdk) : PaymentProcessor {
    override fun pay(amountCents: Long) {
        legacySdk.chargeInDollars(amountCents / 100.0) // adapts the mismatched signature
    }
}

interface FileSystemItem { fun totalSize(): Long }

class File(val size: Long) : FileSystemItem { override fun totalSize() = size }

class Folder(val items: List<FileSystemItem>) : FileSystemItem {
    override fun totalSize() = items.sumOf { it.totalSize() } // treats files and folders alike
}

sealed interface ApiResult<out T> {
    data class Success<T>(val data: T) : ApiResult<T>
    data class Error(val exception: Throwable) : ApiResult<Nothing>
    data object Loading : ApiResult<Nothing>
}

fun render(result: ApiResult<User>) = when (result) {
    is ApiResult.Success -> showUser(result.data)
    is ApiResult.Error -> showError(result.exception)
    ApiResult.Loading -> showSpinner()
    // compiler error if a new subtype is added and not handled here
}

typealias Interceptor = suspend (Request, next: suspend (Request) -> Response) -> Response

val authInterceptor: Interceptor = { req, next -> next(req.withAuthHeader()) }
val retryInterceptor: Interceptor = { req, next -> retryOnFailure { next(req) } }

fun buildChain(interceptors: List<Interceptor>, terminal: suspend (Request) -> Response) =
    interceptors.foldRight(terminal) { interceptor, next ->
        { req: Request -> interceptor(req, next) }
    }

