class CheckoutFacade(
    private val cart: CartService,
    private val payment: PaymentService,
    private val analytics: AnalyticsService
) {
    suspend fun completeCheckout(order: Order): CheckoutResult {
        val total = cart.calculateTotal(order)
        val result = payment.charge(total)
        analytics.trackPurchase(order, result)
        return result
    }
}

class Saga {
    private val compensations = mutableListOf<suspend () -> Unit>()

    suspend fun <T> step(action: suspend () -> T, compensate: suspend () -> Unit): T {
        val result = action()
        compensations.add(0, compensate)
        return result
    }

    suspend fun rollback() = compensations.forEach { it() }
}

// usage: on exception, call saga.rollback() to undo completed steps

interface SecureStorage {
    suspend fun read(key: String): String?
}

class SecureStorageProxy(
    private val real: SecureStorage,
    private val integrityCheck: () -> Boolean
) : SecureStorage {
    override suspend fun read(key: String): String? {
        if (!integrityCheck()) return null // block access if device is compromised
        return real.read(key)
    }
}

