fun interface Specification<T> { fun isSatisfiedBy(candidate: T): Boolean }

fun <T> Specification<T>.and(other: Specification<T>) = Specification<T> { isSatisfiedBy(it) && other.isSatisfiedBy(it) }

val isAdult = Specification<User> { it.age >= 18 }
val isVerified = Specification<User> { it.isVerified }
val eligible = isAdult.and(isVerified)

class DateRange(private val start: LocalDate, private val end: LocalDate) {
    operator fun iterator(): Iterator<LocalDate> = object : Iterator<LocalDate> {
        var current = start
        override fun hasNext() = !current.isAfter(end)
        override fun next() = current.also { current = current.plusDays(1) }
    }
}

